// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type TierListProps = Record<string, any>;

const TierList: React.FC<TierListProps> = ({
  backgroundColor = "#12141a",
  transparentBackground = false,
  durationInSeconds = 12,
  listBgColor = "#1a1d26",
  tiers = [
    {
      tierName: "S Tier",
      tierColor: "#EF8B8B",
      headerTextColor: "#ffffff",
    },
    {
      tierName: "A Tier",
      tierColor: "#EFC185",
      headerTextColor: "#ffffff",
    },
    {
      tierName: "B Tier",
      tierColor: "#EEDB82",
      headerTextColor: "#1a1a1a",
    },
    {
      tierName: "C Tier",
      tierColor: "#DDE97A",
      headerTextColor: "#1a1a1a",
    },
    {
      tierName: "D Tier",
      tierColor: "#AFE67A",
      headerTextColor: "#1a1a1a",
    },
  ],
  items = [
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/manus.png", 
      bgColor: "#ffffff",
      tierIndex: 0,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/claude.webp", 
      bgColor: "#ffffff",
      tierIndex: 1,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/gemini.png", 
      bgColor: "#ffffff",
      tierIndex: 1,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/grok.webp", 
      bgColor: "#ffffff",
      tierIndex: 2,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/qwen.jpeg", 
      bgColor: "#ffffff",
      tierIndex: 3,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/openai.png", 
      bgColor: "#ffffff",
      tierIndex: 4,
    },
    { 
      image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/deepseek.png", 
      bgColor: "#ffffff",
      tierIndex: 4,
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const isLandscape = width > height;

  // Responsive Layout calculations optimized for placing elements in the bottom half
  const boardWidth = isLandscape ? width * 0.56 : width * 0.9;
  const boardHeight = isLandscape ? height * 0.45 : height * 0.35;
  const boardX = isLandscape ? width * 0.05 : (width - boardWidth) / 2;
  const boardY = isLandscape ? height * 0.46 : height * 0.38;

  const trayWidth = isLandscape ? width * 0.32 : width * 0.9;
  const trayHeight = isLandscape ? height * 0.45 : height * 0.15;
  const trayX = isLandscape ? width * 0.63 : (width - trayWidth) / 2;
  const trayY = isLandscape ? height * 0.46 : height * 0.78;

  const numTiers = tiers.length || 1;
  const rowGap = isLandscape ? 10 : 8;
  const boardPadding = 12;
  const rowHeight = (boardHeight - boardPadding * 2 - (numTiers - 1) * rowGap) / numTiers;

  const headerWidth = Math.min(boardWidth * 0.22, 140);
  const cardSize = Math.min(rowHeight * 0.82, 85);
  const itemGap = 10;

  // Flatten items for sequential animation mapping and correct tier placement
  const flatItems: {
    image: string;
    bgColor: string;
    tierIndex: number;
    itemIndex: number;
    globalIndex: number;
    finalX: number;
    finalY: number;
    trayX: number;
    trayY: number;
  }[] = [];

  const tierItemCounts: Record<number, number> = {};

  (items || []).forEach((item, globalIndex) => {
    const rawTierIndex = typeof item.tierIndex === "number" ? item.tierIndex : 0;
    const tierIndex = Math.max(0, Math.min(numTiers - 1, rawTierIndex));

    if (tierItemCounts[tierIndex] === undefined) {
      tierItemCounts[tierIndex] = 0;
    }
    const itemIndex = tierItemCounts[tierIndex];
    tierItemCounts[tierIndex]++;

    flatItems.push({
      image: item.image,
      bgColor: item.bgColor || "#ffffff",
      tierIndex,
      itemIndex,
      globalIndex,
      finalX: 0,
      finalY: 0,
      trayX: 0,
      trayY: 0,
    });
  });

  const numItems = flatItems.length;

  // Map final destination coordinates inside the tier list
  flatItems.forEach((item) => {
    const rowY = boardY + boardPadding + item.tierIndex * (rowHeight + rowGap);
    item.finalX = boardX + boardPadding + headerWidth + itemGap + item.itemIndex * (cardSize + itemGap);
    item.finalY = rowY + (rowHeight - cardSize) / 2;
  });

  // Map tray layout coordinates
  const trayPadding = 16;
  const trayCols = isLandscape ? Math.max(1, Math.floor((trayWidth - trayPadding * 2) / (cardSize + 12))) : numItems;
  const trayColGap = 12;
  const trayRowGap = 12;

  flatItems.forEach((item, idx) => {
    if (isLandscape) {
      const c = idx % trayCols;
      const r = Math.floor(idx / trayCols);
      item.trayX = trayX + trayPadding + c * (cardSize + trayColGap);
      // Shift down slightly in landscape to make room for the elegant tray label
      item.trayY = trayY + trayPadding + 28 + r * (cardSize + trayRowGap);
    } else {
      const totalWidth = numItems * cardSize + (numItems - 1) * trayColGap;
      const startX = trayX + (trayWidth - totalWidth) / 2;
      item.trayX = Math.max(trayX + trayPadding, startX) + idx * (cardSize + trayColGap);
      item.trayY = trayY + (trayHeight - cardSize) / 2;
    }
  });

  // Timing logic for smooth sequential ranking transitions
  const totalActiveFrames = durationInSeconds * fps - 35; // Reserve 1+ second hold at end
  const framesPerItem = numItems > 0 ? Math.max(10, Math.floor(totalActiveFrames / numItems)) : 30;
  const animationFrames = Math.min(28, Math.max(12, Math.floor(framesPerItem * 0.75)));

  // Calculate dynamic properties of each card per frame
  const getItemState = (gIdx: number, currentFrame: number) => {
    const item = flatItems[gIdx];
    const itemStartFrame = gIdx * framesPerItem;
    const landFrame = itemStartFrame + animationFrames;

    if (currentFrame < itemStartFrame) {
      // Resting in Tray
      return {
        x: item.trayX,
        y: item.trayY,
        scale: 1.0,
        isPlaced: false,
        isMoving: false,
        blur: 0,
        shadowStyle: "0px 4px 10px rgba(0,0,0,0.15)",
        zIndex: 10 + gIdx,
      };
    }

    if (currentFrame >= itemStartFrame && currentFrame < landFrame) {
      // Smooth travel from Tray to Tier List row with premium ease curve
      const p = (currentFrame - itemStartFrame) / animationFrames;
      const easedP = Easing.bezier(0.25, 1, 0.4, 1)(p);
      const x = interpolate(easedP, [0, 1], [item.trayX, item.finalX]);
      const y = interpolate(easedP, [0, 1], [item.trayY, item.finalY]);

      // Scale up slightly while moving
      const scale = interpolate(easedP, [0, 0.5, 1], [1.0, 1.18, 1.12]);

      // Real-time Motion Blur calculation based on frame-by-frame velocity
      const prevP = Math.max(0, (currentFrame - 1 - itemStartFrame) / animationFrames);
      const prevEasedP = Easing.bezier(0.25, 1, 0.4, 1)(prevP);
      const prevX = interpolate(prevEasedP, [0, 1], [item.trayX, item.finalX]);
      const prevY = interpolate(prevEasedP, [0, 1], [item.trayY, item.finalY]);
      const dx = x - prevX;
      const dy = y - prevY;
      const speed = Math.sqrt(dx * dx + dy * dy);
      const blur = Math.min(8, speed * 0.12);

      // Evolving drop shadow depth
      const shadowY = interpolate(scale, [1, 1.18], [4, 24]);
      const shadowBlur = interpolate(scale, [1, 1.18], [10, 35]);
      const shadowAlpha = interpolate(scale, [1, 1.18], [0.15, 0.35]);
      const shadowStyle = `0px ${shadowY}px ${shadowBlur}px rgba(0,0,0,${shadowAlpha})`;

      return {
        x,
        y,
        scale,
        isPlaced: false,
        isMoving: true,
        blur,
        shadowStyle,
        zIndex: 100 + gIdx,
      };
    }

    // Impact Landing & Bounce Spring Physics
    const bounceFrame = Math.max(0, currentFrame - landFrame);
    const bounce = spring({
      frame: bounceFrame,
      fps,
      config: { damping: 13, stiffness: 140 },
    });

    const scale = interpolate(bounce, [0, 1], [1.12, 1.0]);
    const shadowY = interpolate(scale, [1, 1.12], [4, 12]);
    const shadowBlur = interpolate(scale, [1, 1.12], [10, 24]);
    const shadowAlpha = interpolate(scale, [1, 1.12], [0.12, 0.22]);
    const shadowStyle = `0px ${shadowY}px ${shadowBlur}px rgba(0,0,0,${shadowAlpha})`;

    return {
      x: item.finalX,
      y: item.finalY,
      scale,
      isPlaced: true,
      isMoving: false,
      blur: 0,
      shadowStyle,
      zIndex: 20 + gIdx,
    };
  };

  // Row pulse intensity evaluator
  const getTierPulse = (tierIdx: number, currentFrame: number) => {
    const tierItems = flatItems.filter((item) => item.tierIndex === tierIdx);
    let maxPulse = 0;

    tierItems.forEach((item) => {
      const landFrame = item.globalIndex * framesPerItem + animationFrames;
      if (currentFrame >= landFrame) {
        const diff = currentFrame - landFrame;
        if (diff >= 0 && diff < 22) {
          const p = interpolate(diff, [0, 22], [1, 0], {
            extrapolateRight: "clamp",
          });
          maxPulse = Math.max(maxPulse, p);
        }
      }
    });

    return maxPulse;
  };

  const containerBgStyle: React.CSSProperties = transparentBackground
    ? { fontFamily: interFamily, width: "100%", height: "100%", position: "relative" }
    : {
        background: `radial-gradient(circle at 50% 30%, #1a1c24 0%, ${backgroundColor} 100%)`,
        fontFamily: interFamily,
        width: "100%",
        height: "100%",
        position: "relative",
        overflow: "hidden",
      };

  return (
    <AbsoluteFill style={containerBgStyle}>
      {/* Premium Glassmorphic Tier List Board */}
      <div
        style={{
          position: "absolute",
          left: boardX,
          top: boardY,
          width: boardWidth,
          height: boardHeight,
          display: "flex",
          flexDirection: "column",
          gap: rowGap,
          backgroundColor: listBgColor,
          backdropFilter: "blur(20px)",
          borderRadius: 24,
          padding: boardPadding,
          boxShadow: "0px 20px 50px rgba(0,0,0,0.35)",
          boxSizing: "border-box",
          border: "1px solid rgba(255, 255, 255, 0.08)",
        }}
      >
        {tiers.map((tier, tierIndex) => {
          const pulse = getTierPulse(tierIndex, frame);
          
          const rowBgColor = pulse > 0
            ? `rgba(255, 255, 255, ${0.03 + pulse * 0.07})`
            : "rgba(255, 255, 255, 0.02)";

          const rowBorder = pulse > 0
            ? `1px solid rgba(255, 255, 255, ${0.05 + pulse * 0.25})`
            : "1px solid rgba(255, 255, 255, 0.04)";

          const headerShadow = pulse > 0
            ? `inset -4px 0px 10px rgba(0,0,0,0.1), 0 0 ${25 * pulse}px ${tier.tierColor}`
            : "inset -4px 0px 10px rgba(0,0,0,0.15)";

          return (
            <div
              key={`tier-${tierIndex}`}
              style={{
                display: "flex",
                height: rowHeight,
                width: "100%",
                backgroundColor: rowBgColor,
                borderRadius: 16,
                border: rowBorder,
                boxShadow: "inset 0px 2px 6px rgba(0,0,0,0.2)",
                overflow: "hidden",
                position: "relative",
                transition: "none",
              }}
            >
              {/* Left Row Header Block */}
              <div
                style={{
                  width: headerWidth,
                  height: "100%",
                  flexShrink: 0,
                  backgroundColor: tier.tierColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  textAlign: "center",
                  padding: "0 12px",
                  boxSizing: "border-box",
                  lineHeight: 1.1,
                  wordBreak: "break-word",
                  fontWeight: 900,
                  fontSize: isLandscape ? 28 : 20,
                  color: tier.headerTextColor,
                  borderTopLeftRadius: 15,
                  borderBottomLeftRadius: 15,
                  boxShadow: headerShadow,
                  textShadow: "0px 2px 4px rgba(0,0,0,0.15)",
                  transition: "none",
                }}
              >
                {tier.tierName}
              </div>
              
              {/* Target Row Content area (transparent filler) */}
              <div style={{ flex: 1 }} />
            </div>
          );
        })}
      </div>

      {/* Unranked Items Tray (Glassmorphic Tray at bottom) */}
      <div
        style={{
          position: "absolute",
          left: trayX,
          top: trayY,
          width: trayWidth,
          height: trayHeight,
          backgroundColor: "rgba(22, 25, 35, 0.55)",
          backdropFilter: "blur(20px)",
          borderRadius: 24,
          padding: trayPadding,
          boxShadow: "0px 20px 50px rgba(0,0,0,0.25)",
          boxSizing: "border-box",
          border: "1px solid rgba(255, 255, 255, 0.06)",
        }}
      >
        {isLandscape && (
          <div
            style={{
              fontSize: 12,
              fontWeight: 800,
              color: "rgba(255,255,255,0.35)",
              textTransform: "uppercase",
              letterSpacing: "1.5px",
              marginBottom: 10,
              position: "absolute",
              top: 14,
              left: 20,
            }}
          >
            Unranked Items
          </div>
        )}

        {/* Square Dotted PNG Placeholders in Tray */}
        {flatItems.map((item, idx) => {
          return (
            <div
              key={`placeholder-${idx}`}
              style={{
                position: "absolute",
                left: item.trayX - trayX,
                top: item.trayY - trayY,
                width: cardSize,
                height: cardSize,
                border: "2px dashed rgba(255, 255, 255, 0.12)",
                borderRadius: 18,
                backgroundColor: "rgba(0, 0, 0, 0.18)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxSizing: "border-box",
              }}
            >
              <div
                style={{
                  color: "rgba(255,255,255,0.1)",
                  fontSize: 18,
                  fontWeight: 700,
                }}
              >
                ?
              </div>
            </div>
          );
        })}
      </div>

      {/* Flying & Bouncing Cards */}
      {flatItems.map((item) => {
        const state = getItemState(item.globalIndex, frame);
        const blurFilter = state.blur > 0.5 ? `blur(${state.blur}px)` : "none";

        return (
          <div
            key={`card-${item.globalIndex}`}
            style={{
              position: "absolute",
              left: state.x,
              top: state.y,
              width: cardSize,
              height: cardSize,
              backgroundColor: item.bgColor,
              borderRadius: 18,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: state.shadowStyle,
              border: "1.5px solid rgba(255, 255, 255, 0.15)",
              transform: `scale(${state.scale})`,
              zIndex: state.zIndex,
              overflow: "hidden",
              filter: blurFilter,
              transition: "none",
              boxSizing: "border-box",
            }}
          >
            <Img
              src={item.image}
              style={{
                width: "72%",
                height: "72%",
                objectFit: "contain",
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default TierList;